/* Synthetic editorial text only for tests. Never loaded by a production provider. */
const news=require('../../../src/lib/news/core.cjs');
const {metadataFor}=require('../../../src/lib/news/sources.cjs');
function editionFor(batch,{count=3}={}){
 const items=news.selectItems(batch.items,'Today',batch.asOf).slice(0,count);if(!items.length)throw Error('Test fixture needs same-day sources');
 const p=(label,ids,kind='analysis')=>({kind,evidenceIds:ids,text:{zh:'合成测试文稿：'+label+'。不代表真实新闻或分析。',en:'Synthetic test narrative: '+label+'. This is not a real news judgment.'}});
 const sources=items.map(i=>({id:i.id,title:i.title,name:i.source,url:i.sourceUrl,type:metadataFor(i).type,publisher:metadataFor(i).publisher,adapterId:metadataFor(i).adapterId,publishedAt:i.publishedAt,excerpt:i.summary,origin:'snapshot'}));
 return {schemaVersion:2,status:'published',date:news.shanghaiDay(batch.asOf),timeZone:'Asia/Shanghai',generatedAt:batch.asOf,sourceSnapshotAt:batch.asOf,provenance:{kind:'human',author:'Synthetic test fixture, not a real editorial author',evidenceReviewed:true,bilingualReviewed:true},sources,executiveOpening:[p('opening one',[items[0].id]),p('opening two',items.map(i=>i.id))],stories:items.map((item,index)=>({id:'synthetic-story-'+index,order:index+1,category:item.category,title:{zh:'合成测试标题 '+index,en:'Synthetic test story '+index},newsIds:[item.id],sources:[sources[index]],verifiedFacts:[p('fact '+index,[item.id],'confirmed')],plainExplanation:p('plain meaning '+index,[item.id]),example:p('concrete hypothetical example '+index,[item.id],'hypothesis'),whyItMatters:[p('mechanism '+index,[item.id])],longTermView:[p('long-range conditional view '+index,[item.id],'hypothesis')],opportunities:[p('opportunity condition '+index,[item.id],'hypothesis')],risks:[p('risk condition '+index,[item.id],'hypothesis')],keywords:[{term:{zh:'合成概念',en:'Synthetic concept'},explanation:{zh:'仅供测试的概念解释',en:'A concept explanation for tests only'}},{term:{zh:'合成验证',en:'Synthetic verification'},explanation:{zh:'仅供测试的验证解释',en:'A verification explanation for tests only'}}],relatedStoryIds:items.length>1?[items[(index+1)%items.length].id]:[],verification:{independentlyConfirmed:false},...(index===0&&items.length>1?{crossAnalysis:[p('cross-source comparison',[item.id,items[1].id])]}:{})})),watchNext:[0,1,2].map(i=>p('observable check '+i,[items[0].id],'hypothesis')),keyword:{term:{zh:'合成测试概念',en:'Synthetic test concept'},explanation:p('concept explanation',[items[0].id]),whyNow:p('why remember now',[items[0].id])},framework:p('optional long-term framework',[items[0].id])};
}
module.exports={editionFor};
